head.script:
scwin.fireDbClick = function(id) {
    var node = WebSquare.wUnit.getDomById($p.id + id);
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 name3 컬럼 셀의 inputType 을 확인한다.
    //1. In the Source tab, check the inputType of the name3 column cell.
    //Verify step 1. inputType="checkcombobox" 
    //1. inputType = "checkcombobox"
    //Test step 2. allOption= 을 확인한다.
    //2. Check allOption =.
    //Verify step 2. allOption="true"
    //2. allOption = "true"
    //Test step 3. 브라우저에서 name3 컬럼의 셀을 임의로 데이터를 체크한 후, 하단에 선택적용 버튼을 클릭한다.
    //3. In the browser, check the data of the cell in the name3 column, and then click the Apply button at the bottom.
    WebSquare.wUnit.addCommand("set", "scwin.fireDbClick($p.id+'gridView1_cell_0_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_itemTable_2_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_itemTable_3_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_btn_confirm').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 3. 체크한 임의의 데이터가 선택된다.
    //3. Any checked data is selected.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_2').innerText", "22 33");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_itemTable_2_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_itemTable_3_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. 다시 하단에 선택해제 버튼을 클릭한다.
    //4. Click the Deselect button at the bottom again.
    WebSquare.wUnit.addCommand("set", "scwin.fireDbClick($p.id+'gridView1_cell_0_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_btn_cancel').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_btn_confirm').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 4. 체크한 임의의 데이터가 해제된다.
    //4. Any checked data is released.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_2').innerText == ''", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_itemTable_2_checkbox').checked", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_itemTable_3_checkbox').checked", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
